import * as T from './vendor/three.module.js';
import {SITE} from './site-layout.js';
import {YARD_FENCES,FREIGHT_GATE} from './yard-layout.js';
export function drawNoticeMap(c){const w=c.canvas.width,h=c.canvas.height;c.fillStyle='#baad88';c.fillRect(0,0,w,h);c.fillStyle='#343d32';c.font='bold 34px monospace';c.fillText('EXIT NINE / SITE PLAN',36,55);c.font='23px sans-serif';c.fillText('站点地图 · 电闸请从前门绕行',36,92);const sc=12,x=v=>300+v*sc,y=v=>152+(v+5)*sc;c.fillStyle='#747862';c.fillRect(32,117,536,24);c.fillStyle='#ece0b9';c.font='20px sans-serif';c.fillText('公路 / HIGHWAY',210,138);
 const rect=(r,fill)=>{c.fillStyle=fill;c.fillRect(x(r.x0),y(r.z0),(r.x1-r.x0)*sc,(r.z1-r.z0)*sc);c.strokeStyle='#303b31';c.lineWidth=3;c.strokeRect(x(r.x0),y(r.z0),(r.x1-r.x0)*sc,(r.z1-r.z0)*sc);};rect(SITE.shop,'#818d74');rect(SITE.stock,'#979579');rect(SITE.office,'#a19b7c');c.fillStyle='#25362d';c.font='bold 23px sans-serif';c.fillText('营业区',x(-4),y(2));c.fillText('后仓',x(-3),y(14));c.font='18px sans-serif';c.fillText('员工室',x(12),y(12));c.fillText('卸货院',x(-1),y(27));
 c.strokeStyle='#61674e';c.lineWidth=7;for(const z of[1,3,5]){c.beginPath();c.moveTo(x(-2),y(z));c.lineTo(x(6),y(z));c.stroke();}c.fillStyle='#3f4939';for(const px of[-7,0,7])c.fillRect(x(px)-10,y(-12)-13,20,26);c.font='18px sans-serif';c.fillText('加油区',x(-3),y(-9));c.strokeStyle='#aa552c';c.lineWidth=5;c.setLineDash([8,4]);for(const p of YARD_FENCES){c.beginPath();c.moveTo(x(p.x-p.w/2),y(p.z-p.d/2));c.lineTo(x(p.x+p.w/2),y(p.z+p.d/2));c.stroke();}c.setLineDash([]);c.fillStyle='#a46932';c.fillRect(x(SITE.breaker.x)-5,y(SITE.breaker.z)-5,10,10);c.font='18px sans-serif';c.fillText('电闸',x(17),y(17.5));c.fillRect(x(FREIGHT_GATE.x)-3,y(FREIGHT_GATE.z-4),6,8*sc);c.fillStyle='#3d4334';c.fillText('货运门',x(13),y(32));
 c.strokeStyle='#b78436';c.lineWidth=4;c.beginPath();for(const [i,p]of [[0,[-8,-1]],[1,[.5,-3.5]],[2,[.5,-6.5]],[3,[19.6,-6.5]],[4,[19.6,18]]]){i?c.lineTo(x(p[0]),y(p[1])):c.moveTo(x(p[0]),y(p[1]));}c.stroke();c.beginPath();c.moveTo(x(19.6)-6,y(18)-12);c.lineTo(x(19.6),y(18));c.lineTo(x(19.6)+6,y(18)-12);c.stroke();c.fillStyle='#9b512d';c.beginPath();c.arc(x(-9),y(-.8),6,0,Math.PI*2);c.fill();c.font='21px sans-serif';c.fillText('你在柜台 · E 查看详细地图',36,h-62);c.font='18px sans-serif';c.fillText('日常也可按 M 查看 / 后仓不是通往电闸的出口',36,h-27);}
export function installNoticeMap(w){const canvas=document.createElement('canvas');canvas.width=600;canvas.height=800;drawNoticeMap(canvas.getContext('2d'));const tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;const m=new T.Mesh(new T.PlaneGeometry(.82,1.10),new T.MeshStandardMaterial({map:tex,roughness:1}));m.position.set(-10.795,1.90,1.32);m.rotation.y=Math.PI/2;m.name='counter-noticeboard-map';m.userData.target={id:'map'};w.scene.add(m);w.noticeMap=m;w.target('map',null,-10.75,1.90,1.32,'查看公告板上的站点地图');}
